/* Geometry-to-physics walkthrough loader (D-025).
 * Reads ../AutoGenerated/geometry_to_physics.json and draws a numbered stepper
 * grouped by stage. Text is set with textContent; only the engine's own figure
 * SVG is inserted as markup. */
(function () {
  'use strict';
  var DATA_URL = '../AutoGenerated/geometry_to_physics.json';
  var TONE_LABEL = { ok: 'derived / geometric', fitted: 'calibrated / fitted',
                     fail: 'failing', open: 'open' };

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined && text !== null) n.textContent = text;
    return n;
  }

  function fmt(v) {
    if (v === null || v === undefined) return 'n/a';
    if (typeof v === 'number') {
      var a = Math.abs(v);
      return (a !== 0 && (a < 1e-3 || a >= 1e6)) ? v.toExponential(4) : String(+v.toPrecision(6));
    }
    return String(v);
  }

  function row(label, node) {
    var r = el('div', 'gp-row');
    r.appendChild(el('b', null, label));
    r.appendChild(typeof node === 'string' ? document.createTextNode(node) : node);
    return r;
  }

  function experimentText(x) {
    if (!x || x.verdict === 'NO_TEST') return 'no experimental test for this quantity';
    var s = 'measured ' + fmt(x.value);
    if (x.uncertainty !== null && x.uncertainty !== undefined) s += ' +/- ' + fmt(x.uncertainty);
    if (x.source) s += ' (' + x.source + ')';
    s += '; pull ' + fmt(x.pull) + ' sigma; verdict ' + x.verdict;
    return s;
  }

  function figureNode(step) {
    var fig = el('figure', 'gp-fig');
    var holder = el('div');
    holder.innerHTML = step.figure_svg;   // engine-generated SVG
    fig.appendChild(holder);
    fig.appendChild(el('figcaption', null, step.figure_caption || ''));
    return fig;
  }

  function cardHead(step) {
    var h = el('div', 'gp-head');
    h.appendChild(el('span', 'gp-num', step.order + '.'));
    h.appendChild(el('span', 'gp-sym', step.output_symbol));
    var b = el('span', 'gp-badge', step.status);
    b.title = TONE_LABEL[step.tone] || '';
    h.appendChild(b);
    if (step.experiment && step.experiment.verdict && step.experiment.verdict !== 'NO_TEST') {
      h.appendChild(el('span', 'gp-badge', step.experiment.verdict));
    }
    return h;
  }

  function formulaNode(step) {
    var f = step.formula || {};
    var n = el('div', 'gp-formula', f.plain_text || 'OPEN');
    if (f.latex) n.title = f.latex;
    return n;
  }

  function buildCard(step) {
    var c = el('article', 'gp-card tone-' + step.tone);
    c.id = 'step-' + step.id;
    c.appendChild(cardHead(step));
    c.appendChild(row('Geometric input:', step.geometric_input));
    c.appendChild(row('Operation:', step.operation));
    c.appendChild(row('Formula:', formulaNode(step)));
    c.appendChild(row('Value:', el('span', 'gp-value', fmt(step.value))));
    c.appendChild(row('Experiment:', experimentText(step.experiment)));
    if (step.figure_svg) c.appendChild(figureNode(step));
    var why = Object.keys(step.why || {});
    if (why.length) {
      c.appendChild(row('OPEN:', el('span', 'gp-why', why.map(function (k) { return step.why[k]; }).join('; '))));
    }
    if (step.section_href) {
      var a = el('a', 'gp-link', 'Paper section ' + step.section_id);
      a.href = step.section_href;
      c.appendChild(a);
    }
    return c;
  }

  function renderSummary(doc) {
    var box = document.getElementById('gp-summary');
    box.textContent = '';
    var s = doc.summary;
    box.appendChild(el('strong', null, s.steps + ' steps:'));
    var tones = [['ok', '#2fbf71'], ['fitted', '#f0a030'], ['fail', '#e5484d'], ['open', '#adb5bd']];
    tones.forEach(function (t) {
      var n = (s.by_tone || {})[t[0]] || 0;
      var chip = el('span', 'gp-count', n + ' ' + TONE_LABEL[t[0]]);
      chip.style.color = t[1];
      box.appendChild(chip);
    });
    var statuses = Object.keys(s.by_status || {}).map(function (k) { return k + ' ' + s.by_status[k]; });
    box.appendChild(el('span', 'gp-why', 'by registry status: ' + statuses.join(', ')));
  }

  function renderStages(doc) {
    var nav = document.getElementById('gp-stages');
    var root = document.getElementById('gp-steps');
    doc.stages.forEach(function (st, i) {
      var link = el('a', null, (i + 1) + '. ' + st.label);
      link.href = '#stage-' + st.id;
      nav.appendChild(link);
      var sec = el('section', 'gp-stage');
      sec.id = 'stage-' + st.id;
      sec.appendChild(el('h2', null, (i + 1) + '. ' + st.label));
      doc.steps.filter(function (s) { return s.stage === st.id; })
        .forEach(function (s) { sec.appendChild(buildCard(s)); });
      root.appendChild(sec);
    });
  }

  function fail(msg) {
    var e = document.getElementById('gp-error');
    e.textContent = msg;
    e.hidden = false;
    document.getElementById('gp-summary').textContent = '';
  }

  function init() {
    fetch(DATA_URL).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status + ' for geometry_to_physics.json');
      return r.json();
    }).then(function (doc) {
      renderSummary(doc);
      renderStages(doc);
    }).catch(function (err) { fail('Could not load the walkthrough: ' + err.message); });
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
